  1821  /** @brief Calculates the size of a matlab variable in bytes
  1822   *
  1823   * @ingroup MAT
  1824   * @param matvar matlab variable
  1825   * @returns size of the variable in bytes, or 0 on error
  1826   */
  1827  size_t
  1828  Mat_VarGetSize(matvar_t *matvar)
  1829  {
  1830      int err;
  1831      size_t i;
  1832      size_t bytes = 0, overhead = 0, ptr = 0;
  1833
  1834  #if defined(_WIN64) || (defined(__SIZEOF_POINTER__) && (__SIZEOF_POINTER__ == 8)) || (defined(SIZEOF_VOID_P) && (SIZEOF_VOID_P == 8))
  1835      /* 112 bytes cell/struct overhead for 64-bit system */
  1836      overhead = 112;
  1837      ptr = 8;
  1838  #elif defined(_WIN32) || (defined(__SIZEOF_POINTER__) && (__SIZEOF_POINTER__ == 4)) || (defined(SIZEOF_VOID_P) && (SIZEOF_VOID_P == 4))
  1839      /* 60 bytes cell/struct overhead for 32-bit system */
  1840      overhead = 60;
  1841      ptr = 4;
  1842  #endif
  1843
  1844      if ( matvar->class_type == MAT_C_STRUCT ) {
  1845          matvar_t **fields = (matvar_t**)matvar->data;
  1846          size_t field_name_length;
  1847          if ( NULL != fields ) {
  1848              size_t nelems_x_nfields = matvar->internal->num_fields;
  1849              err = SafeMulDims(matvar, &nelems_x_nfields);
  1850              err |= SafeMul(&bytes, nelems_x_nfields, overhead);
  1851              if ( err )
  1852                  return 0;
  1853
  1854              for ( i = 0; i < nelems_x_nfields; i++ ) {
  1855                  if ( NULL != fields[i] ) {
  1856                      if ( MAT_C_EMPTY != fields[i]->class_type ) {
  1857                          err = SafeAdd(&bytes, bytes, Mat_VarGetSize(fields[i]));
  1858                          if ( err )
  1859                              return 0;
  1860                      } else {
  1861                          bytes -= overhead;
  1862                          bytes += ptr;
  1863                      }
  1864                  }
  1865              }
  1866          }
  1867          err = SafeMul(&field_name_length, 64 /* max field name length */, matvar->internal->num_fields);
  1868          err |= SafeAdd(&bytes, bytes, field_name_length);
  1869          if ( err )
  1870              return 0;
  1871      } else if ( matvar->class_type == MAT_C_CELL ) {
  1872          matvar_t **cells = (matvar_t**)matvar->data;
  1873          if ( NULL != cells ) {
  1874              size_t nelems = matvar->nbytes / matvar->data_size;
  1875              err = SafeMul(&bytes, nelems, overhead);
  1876              if ( err )
  1877                  return 0;
  1878
  1879              for ( i = 0; i < nelems; i++ ) {
  1880                  if ( NULL != cells[i] ) {
  1881                      if ( MAT_C_EMPTY != cells[i]->class_type ) {
  1882                          err = SafeAdd(&bytes, bytes, Mat_VarGetSize(cells[i]));
  1883                          if ( err )
  1884                              return 0;
  1885                      } else {
  1886                          bytes -= overhead;
  1887                          bytes += ptr;
  1888                      }
  1889                  }
  1890              }
  1891          }
  1892      } else if ( matvar->class_type == MAT_C_SPARSE ) {
  1893          mat_sparse_t *sparse = (mat_sparse_t*)matvar->data;
  1894          if ( NULL != sparse ) {
  1895              size_t sparse_size = 0;
  1896              err = SafeMul(&bytes, sparse->ndata, Mat_SizeOf(matvar->data_type));
  1897              if ( err )
  1898                  return 0;
  1899
  1900              if ( matvar->isComplex ) {
  1901                  err = SafeMul(&bytes, bytes, 2);
  1902                  if ( err )
  1903                      return 0;
  1904              }
  1905
  2240      }
  2241
  2242      return err;
  2243  }
